	unit string
}

// NewInt64CounterConfig returns an int64 counter config with opts applied.
func NewInt64CounterConfig(opts ...Int64CounterOption) Int64CounterConfig {
	var cfg Int64CounterConfig
	for _, opt := range opts {
		cfg = opt.applyInt64Counter(cfg)
	}
	return cfg
}

// Unit returns the configured unit.
