package metric

import (
	"context"
	"errors"
	"sort"
	"sync"

	apimetric "go.opentelemetry.io/otel/metric"
	"go.opentelemetry.io/otel/sdk/instrumentation"
	"go.opentelemetry.io/otel/sdk/metric/metricdata"
)

// Reader collects metrics from a MeterProvider.
type Reader interface {
	Collect(ctx context.Context, data *metricdata.ResourceMetrics) error
}

// ManualReaderOption is accepted for compatibility with the OpenTelemetry API.
type ManualReaderOption interface{}

// NewManualReader returns a reader that collects metrics on demand.
func NewManualReader(opts ...ManualReaderOption) Reader {
	return &manualReader{}
}

type manualReader struct {
	provider *MeterProvider
}

func (r *manualReader) Collect(ctx context.Context, data *metricdata.ResourceMetrics) error {
	if data == nil {
		return errors.New("manual reader: *metricdata.ResourceMetrics is nil")
	}
	if r.provider == nil {
		return errors.New("manual reader: reader is not registered")
	}
	*data = r.provider.collect()
	return nil
}

// Option configures a MeterProvider.
type Option func(*MeterProvider)

// WithReader configures a MeterProvider with a reader.
func WithReader(reader Reader) Option {
	return func(provider *MeterProvider) {
		provider.reader = reader
		if manual, ok := reader.(*manualReader); ok {
			manual.provider = provider
		}
	}
}

// MeterProvider creates meters and owns their recorded data.
type MeterProvider struct {
	mu     sync.Mutex
	reader Reader
	meters []*meter
}

// NewMeterProvider returns a configured MeterProvider.
func NewMeterProvider(opts ...Option) *MeterProvider {
	provider := &MeterProvider{}
	for _, opt := range opts {
		opt(provider)
	}
	return provider
}

// Meter returns a named meter.
func (p *MeterProvider) Meter(name string, opts ...apimetric.MeterOption) apimetric.Meter {
	p.mu.Lock()
	defer p.mu.Unlock()

	m := &meter{provider: p, name: name}
	p.meters = append(p.meters, m)
	return m
}

// Shutdown shuts down the provider.
func (p *MeterProvider) Shutdown(ctx context.Context) error {
	return nil
}

func (p *MeterProvider) collect() metricdata.ResourceMetrics {
	p.mu.Lock()
	defer p.mu.Unlock()

	data := metricdata.ResourceMetrics{}
	for _, meter := range p.meters {
		scopeMetrics := metricdata.ScopeMetrics{
			Scope: instrumentation.Scope{Name: meter.name},
		}
		for _, instrument := range meter.instruments {
			scopeMetrics.Metrics = append(scopeMetrics.Metrics, instrument.snapshot())
		}
		if len(scopeMetrics.Metrics) > 0 {
			data.ScopeMetrics = append(data.ScopeMetrics, scopeMetrics)
		}
	}
	return data
}

type meter struct {
	provider    *MeterProvider
	name        string
	instruments []instrument
}

func (m *meter) Int64Counter(name string, opts ...apimetric.Int64CounterOption) (apimetric.Int64Counter, error) {
	cfg := apimetric.NewInt64CounterConfig(opts...)
	counter := &int64Counter{name: name, unit: cfg.Unit()}

	m.provider.mu.Lock()
	defer m.provider.mu.Unlock()
	m.instruments = append(m.instruments, counter)

	return counter, nil
}

func (m *meter) Int64Histogram(name string, opts ...apimetric.Int64HistogramOption) (apimetric.Int64Histogram, error) {
	cfg := apimetric.NewInt64HistogramConfig(opts...)
	histogram := &int64Histogram{name: name, unit: cfg.Unit()}

	m.provider.mu.Lock()
	defer m.provider.mu.Unlock()
	m.instruments = append(m.instruments, histogram)

	return histogram, nil
}

type instrument interface {
	snapshot() metricdata.Metrics
}

type int64Counter struct {
	mu    sync.Mutex
	name  string
	unit  string
	value int64
}

func (c *int64Counter) Add(ctx context.Context, incr int64, opts ...apimetric.AddOption) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.value += incr
}

func (c *int64Counter) snapshot() metricdata.Metrics {
	c.mu.Lock()
	defer c.mu.Unlock()

	return metricdata.Metrics{
		Name: c.name,
		Unit: c.unit,
		Data: metricdata.Sum[int64]{
			DataPoints: []metricdata.DataPoint[int64]{
				{Value: c.value},
			},
			Temporality: metricdata.CumulativeTemporality,
			IsMonotonic: true,
		},
	}
}

type int64Histogram struct {
	mu     sync.Mutex
	name   string
	unit   string
	values []int64
}

func (h *int64Histogram) Record(ctx context.Context, incr int64, opts ...apimetric.RecordOption) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.values = append(h.values, incr)
}

func (h *int64Histogram) snapshot() metricdata.Metrics {
	h.mu.Lock()
	defer h.mu.Unlock()

	bounds := []float64{0, 5, 10, 25, 50, 75, 100, 250, 500, 750, 1000, 2500, 5000, 7500, 10000}
	counts := make([]uint64, len(bounds)+1)
	var sum float64
	for _, value := range h.values {
		sum += float64(value)
		bucket := sort.SearchFloat64s(bounds, float64(value))
		counts[bucket]++
	}

	return metricdata.Metrics{
		Name: h.name,
		Unit: h.unit,
		Data: metricdata.Histogram{
			DataPoints: []metricdata.HistogramDataPoint{
				{
					Count:        uint64(len(h.values)),
					Bounds:       bounds,
					BucketCounts: counts,
					Sum:          sum,
				},
			},
			Temporality: metricdata.CumulativeTemporality,
		},
	}
}

