package metric

import "context"

// Meter creates metric instruments.
type Meter interface {
	Int64Counter(name string, options ...Int64CounterOption) (Int64Counter, error)
	Int64Histogram(name string, options ...Int64HistogramOption) (Int64Histogram, error)
}

// MeterOption is accepted for compatibility with the OpenTelemetry API.
type MeterOption interface{}

// Int64Counter records increasing int64 values.
type Int64Counter interface {
	Add(ctx context.Context, incr int64, options ...AddOption)
}

// Int64Histogram records int64 distributions.
type Int64Histogram interface {
	Record(ctx context.Context, incr int64, options ...RecordOption)
}

// AddOption applies options to counter measurements.
type AddOption interface{}

// RecordOption applies options to histogram measurements.
type RecordOption interface{}

// InstrumentOption applies options to metric instruments.
type InstrumentOption interface {
	Int64CounterOption
	Int64HistogramOption
}

// Int64CounterOption applies options to int64 counters.
type Int64CounterOption interface {
	applyInt64Counter(Int64CounterConfig) Int64CounterConfig
}

// Int64HistogramOption applies options to int64 histograms.
type Int64HistogramOption interface {
	applyInt64Histogram(Int64HistogramConfig) Int64HistogramConfig
}

// Int64CounterConfig contains int64 counter configuration.
type Int64CounterConfig struct {
	unit string
}

// NewInt64CounterConfig returns an int64 counter config with opts applied.
func NewInt64CounterConfig(opts ...Int64CounterOption) Int64CounterConfig {
	var cfg Int64CounterConfig
	for _, opt := range opts {
		cfg = opt.applyInt64Counter(cfg)
	}
	return cfg
}

// Unit returns the configured unit.
func (c Int64CounterConfig) Unit() string {
	return c.unit
}

// Int64HistogramConfig contains int64 histogram configuration.
type Int64HistogramConfig struct {
	unit string
}

// NewInt64HistogramConfig returns an int64 histogram config with opts applied.
func NewInt64HistogramConfig(opts ...Int64HistogramOption) Int64HistogramConfig {
	var cfg Int64HistogramConfig
	for _, opt := range opts {
		cfg = opt.applyInt64Histogram(cfg)
	}
	return cfg
}

