package metricdata

import (
	"time"

	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric/unit"
	"go.opentelemetry.io/otel/sdk/instrumentation"
	"go.opentelemetry.io/otel/sdk/resource"
)

// ResourceMetrics is a collection of scope metrics.
type ResourceMetrics struct {
	Resource     *resource.Resource
	ScopeMetrics []ScopeMetrics
}

// ScopeMetrics is a collection of metrics produced by a meter.
type ScopeMetrics struct {
	Scope   instrumentation.Scope
	Metrics []Metrics
}

// Metrics contains aggregated data from an instrument.
type Metrics struct {
	Name        string
	Description string
	Unit        unit.Unit
	Data        Aggregation
}

// Aggregation is metric aggregation data.
type Aggregation interface {
	privateAggregation()
}

// Gauge represents the current value of an instrument.
type Gauge[N int64 | float64] struct {
	DataPoints []DataPoint[N]
}

func (Gauge[N]) privateAggregation() {}

// Sum represents the sum of all measurements from an instrument.
type Sum[N int64 | float64] struct {
	DataPoints  []DataPoint[N]
	Temporality Temporality
	IsMonotonic bool
}

func (Sum[N]) privateAggregation() {}

// DataPoint is a single sum data point.
type DataPoint[N int64 | float64] struct {
	Attributes attribute.Set
	StartTime  time.Time `json:",omitempty"`
	Time       time.Time `json:",omitempty"`
	Value      N
}

// Histogram represents a histogram aggregation.
type Histogram struct {
	DataPoints  []HistogramDataPoint
	Temporality Temporality
}

func (Histogram) privateAggregation() {}

// HistogramDataPoint is a single histogram data point.
type HistogramDataPoint struct {
	Attributes   attribute.Set
	StartTime    time.Time
	Time         time.Time
	Count        uint64
	Bounds       []float64
	BucketCounts []uint64
	Min          Extrema
	Max          Extrema
	Sum          float64
}

// Extrema is the minimum or maximum value of a dataset.
type Extrema struct {
	value float64
	valid bool
}

// NewExtrema returns an Extrema set to v.
func NewExtrema(v float64) Extrema {
	return Extrema{value: v, valid: true}
}

// Value returns the Extrema value and true if the Extrema is defined.
func (e Extrema) Value() (v float64, defined bool) {
	return e.value, e.valid
}

// Temporality describes whether an aggregation is cumulative or delta.
type Temporality uint8

const (
	undefinedTemporality Temporality = iota
	CumulativeTemporality
	DeltaTemporality
)

// MarshalText returns the byte encoding of t.
func (t Temporality) MarshalText() ([]byte, error) {
	return []byte(t.String()), nil
}

func (t Temporality) String() string {
	switch t {
	case CumulativeTemporality:
		return "CumulativeTemporality"
	case DeltaTemporality:
		return "DeltaTemporality"
	default:
		return "UnknownTemporality"
	}
}

